import { Swap as SwapPrimitive, useSwap, useSwapContext } from '@ark-ui/solid/swap';
import type { ComponentProps } from 'solid-js';
import { splitProps } from 'solid-js';
import { cn } from '@/lib/moduix/cn';

type SwapAnimation = 'fade' | 'scale' | 'rotate' | 'flip' | (string & {});

type SwapRootProps = ComponentProps<typeof SwapPrimitive.Root> & {
  animation?: SwapAnimation;
};

type SwapRootProviderProps = ComponentProps<typeof SwapPrimitive.RootProvider> & {
  animation?: SwapAnimation;
};

function SwapRoot(props: SwapRootProps) {
  const [local, others] = splitProps(props, ['animation', 'class']);

  return (
    <SwapPrimitive.Root
      data-slot="swap-root"
      data-animation={local.animation ?? 'scale'}
      class={cn(
        "group/swap inline-grid [grid-template-areas:'swap'] place-items-center align-middle data-[animation=flip]:[perspective:24rem]",
        local.class,
      )}
      {...others}
    />
  );
}

function SwapRootProvider(props: SwapRootProviderProps) {
  const [local, others] = splitProps(props, ['animation', 'class']);

  return (
    <SwapPrimitive.RootProvider
      data-slot="swap-root-provider"
      data-animation={local.animation ?? 'scale'}
      class={cn(
        "group/swap inline-grid [grid-template-areas:'swap'] place-items-center align-middle data-[animation=flip]:[perspective:24rem]",
        local.class,
      )}
      {...others}
    />
  );
}

function SwapIndicator(props: ComponentProps<typeof SwapPrimitive.Indicator>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SwapPrimitive.Indicator
      data-slot="swap-indicator"
      class={cn(
        'inline-flex [grid-area:swap] items-center justify-center text-inherit group-data-[animation=fade]/swap:data-[state=open]:animate-moduix-swap-fade-enter group-data-[animation=fade]/swap:data-[state=closed]:animate-moduix-swap-fade-exit group-data-[animation=scale]/swap:data-[state=open]:animate-moduix-swap-scale-enter group-data-[animation=scale]/swap:data-[state=closed]:animate-moduix-swap-scale-exit group-data-[animation=rotate]/swap:data-[state=open]:animate-moduix-swap-rotate-enter group-data-[animation=rotate]/swap:data-[state=closed]:animate-moduix-swap-rotate-exit group-data-[animation=flip]/swap:[backface-visibility:hidden] group-data-[animation=flip]/swap:data-[state=open]:animate-moduix-swap-flip-enter group-data-[animation=flip]/swap:data-[state=closed]:animate-moduix-swap-flip-exit motion-reduce:[animation-delay:0ms] motion-reduce:[animation-duration:1ms]',
        local.class,
      )}
      {...others}
    />
  );
}

type SwapComponent = typeof SwapRoot & {
  Root: typeof SwapRoot;
  RootProvider: typeof SwapRootProvider;
  Indicator: typeof SwapIndicator;
  useSwap: typeof useSwap;
};

const Swap: SwapComponent = Object.assign(SwapRoot, {
  Root: SwapRoot,
  RootProvider: SwapRootProvider,
  Indicator: SwapIndicator,
  useSwap,
});

export { Swap, useSwap, useSwapContext, type SwapAnimation };
